def migrar_gobierno_existente(apps, schema_editor):
    Recurso = apps.get_model('webcitt', 'Recurso')
    Carpeta = apps.get_model('webcitt', 'CarpetaRecurso')
    Modulo = apps.get_model('webcitt', 'ModuloUnidad')
    Recurso.objects.filter(restringido=True).update(visibilidad='restringida')
    for carpeta in Carpeta.objects.filter(unidad__dependencia='plantas_piloto').select_related('modulo_config'):
        if not carpeta.modulo_config_id:
            carpeta.modulo_config = Modulo.objects.filter(
                unidad_id=carpeta.unidad_id,
                clave='informacion-general',
            ).first()
        clave = carpeta.modulo_config.clave if carpeta.modulo_config_id else 'informacion-general'
        carpeta.seccion_planta = SECCION_POR_MODULO.get(clave, '1.5')
        carpeta.save(update_fields=['modulo_config', 'seccion_planta'])


